import React from 'react';
import { Search, X } from 'lucide-react';

/**
 * Buscador de platos por nombre. Con catálogos de 50+ productos, escribir
 * es más rápido que navegar categoría por categoría — al escribir, la
 * grilla busca en todo el menú sin importar la categoría activa
 * (ver utils/orderForm.js#filterOrderProducts).
 */
const ProductSearchBar = ({ value, onChange, placeholder = 'Buscar plato por nombre...' }) => (
  <div className="order-search">
    <Search size={17} className="order-search-icon" />
    <input
      type="text"
      className="order-search-input"
      placeholder={placeholder}
      value={value}
      onChange={(e) => onChange(e.target.value)}
    />
    {value && (
      <button
        type="button"
        className="order-search-clear"
        onClick={() => onChange('')}
        aria-label="Limpiar búsqueda"
      >
        <X size={15} />
      </button>
    )}
  </div>
);

export default ProductSearchBar;
